export function isModuleAvailableForLocale(module: ModuleManifest, locale: string) {
  return module.locales.includes(locale as "zh" | "en");
}

export function getLocalizedModule(module: ModuleManifest, locale: string): ModuleManifest {
  if (locale !== "en" || !englishCopies[module.id]) return module;
  const copy = englishCopies[module.id];
  return {
    ...module,
    title: copy.title,
    shortTitle: copy.shortTitle,
    summary: copy.summary,
    description: copy.description,
    lessons: module.lessons.map((lesson) => {
      const lessonCopy = copy.lessons[lesson.id];
      return lessonCopy ? { ...lesson, ...lessonCopy } : lesson;
    }),
  };
}

export function getEnglishModuleCopy(moduleId: string) {
  return englishCopies[moduleId];
}
